for _ in range(2):
    if os.path.exists('temp.txt'):
        os.remove('temp.txt')
        print('deleted')
    else:
        print('The file does not exist')

import csv

open('csv_example.csv', 'w').write('name,country,city\nAsabeneh,Finland,Helsinki\n')
with open('csv_example.csv') as f:
    for i, row in enumerate(csv.reader(f, delimiter=',')):
        if i == 0:
            print('Column names are:', ', '.join(row))
        else:
            print(f'{row[0]} lives in {row[1]}, {row[2]}.')
